python3 - <<'EOF'
import re
txt = open('IP/IO/ICsprout_55LLULP1233_IO_251013/cdl/ICSIOA_N55_3P3.cdl').read()
# parse subcircuits
subs = {}
cur = None
for line in txt.splitlines():
    line = line.strip()
    m = re.match(r'\.SUBCKT\s+(\S+)(.*)', line)
    if m:
        cur = m.group(1)
        subs[cur] = {'M': 0, 'X': []}
        continue
    if line.startswith('.ENDS'):
        cur = None
        continue
    if cur is None or line.startswith('*'):
        continue
    if re.match(r'^M\S*\s', line):
        subs[cur]['M'] += 1
    if re.match(r'^X\S*\s', line):
        mm = re.search(r'/\s*(\S+)\s*$', line)
        if mm:
            subs[cur]['X'].append(mm.group(1))
        else:
            # inline device like re_ppo_sab_2t without slash
            tok = line.split()
            subs[cur]['X'].append(tok[2])

def count(name, seen=None):
    if seen is None: seen = set()
    if name in seen: return 0
    seen = seen | {name}
    s = subs.get(name)
    if s is None: return 0
    return s['M'] + sum(count(x, seen) for x in s['X'])

for c in ['P65_1233_PBMUX', 'P65_1233_PWE', 'P65_1233_PAR', 'P65_1233_VDD1', 'P65_1233_CUT', 'P65_1233_VSS3']:
    s = subs[c]
    print(c, 'topM=', s['M'], 'topX=', len(s['X']), 'recursive MOS=', count(c))
print('total subckts:', len(subs))
EOF
